<template><div class="app-container ps-page"><h2>检索评测与诊断</h2><el-alert v-if="error||pageError" :title="error||pageError" type="error" :closable="false"/><div class="ps-toolbar"><el-button v-hasPermi="['paismart:eval:run']" type="primary" @click="open=true">发起评测</el-button><el-button :loading="loading" @click="load()">刷新</el-button></div><el-form inline><el-form-item label="评测名称"><el-input v-model="query.keyword" clearable @keyup.enter="load(true)"/></el-form-item><el-form-item label="状态"><el-select v-model="query.state" clearable><el-option v-for="s in ['QUEUED','RUNNING','COMPLETE','COMPLETED_WITH_ERRORS']" :key="s" :label="stateLabel(s)" :value="s"/></el-select></el-form-item><el-button @click="load(true)">查询</el-button></el-form><el-table :data="rows" v-loading="loading"><el-table-column prop="label" label="评测名称" min-width="240"/><el-table-column label="状态" width="130"><template #default="{row}">{{stateLabel(row.state)}}</template></el-table-column><el-table-column prop="topK" label="Top K" width="100"/><el-table-column prop="createdAt" label="创建时间" min-width="180"/><el-table-column label="操作" width="240"><template #default="{row}"><el-button link type="primary" @click="report(row.id)">报告与复核</el-button><el-button v-if="row.jobId" link @click="showJob(row)">处理进度</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.pageNum" :page-size="query.pageSize" :total="total" layout="total,prev,pager,next" @current-change="load()"/><el-dialog v-model="open" title="发起受控评测" width="min(800px,95vw)"><el-alert title="评测会消耗检索与模型预算；使用当前账号允许的知识范围，最多 500 个样本。" type="info" :closable="false" class="ps-section"/><el-form label-width="100px"><el-form-item label="评测名称" required><el-input v-model="form.label" maxlength="100"/></el-form-item><el-form-item label="知识范围"><el-select v-model="form.spaceId" clearable placeholder="全部有权空间"><el-option v-for="s in spaces" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="Top K"><el-input-number v-model="form.topK" :min="1" :max="20"/></el-form-item><el-form-item label="读取评测集"><input type="file" accept=".jsonl,.ndjson,.txt" aria-label="读取本地 JSONL 评测集" @change="readFile"/></el-form-item><el-form-item label="JSONL 内容" required><el-input v-model="form.inlineJsonl" type="textarea" :rows="10" placeholder='每行一个 JSON 对象，包含 question 或 query，以及独立参考答案 referenceAnswer；可选 expectedDocumentIds/expectedFileNames'/></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">提交评测</el-button></template></el-dialog><JobDialog v-model="jobOpen" :initial="job" @done="load()"/></div></template>
<script setup lang="ts">
import { onMounted,ref,shallowRef } from 'vue'
import { useRouter } from 'vue-router'
import { createEvaluation,listEvaluations } from '@/api/paismart/governance'
import { listSpaces } from '@/api/paismart/spaces'
import type { Evaluation,Id,Job,Space } from '@/types/paismart'
import JobDialog from '../../components/JobDialog.vue'
import { errorText,stateLabel,usePage } from '../../composables/usePage'
import { validateDataset } from '../../composables/evaluationDataset'
import '../../common.css'
const router=useRouter(),{rows,total,query,loading,error,load}=usePage(listEvaluations),spaces=shallowRef<Space[]>([]),job=shallowRef<Job>(),pageError=ref(''),formError=ref(''),open=ref(false),jobOpen=ref(false),saving=ref(false),form=ref({label:'',spaceId:undefined as Id|undefined,topK:5,inlineJsonl:''})
async function readFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;formError.value='';if(file.size>5*1024*1024){formError.value='评测集文件超过 5 MB，请缩小样本集';return}form.value.inlineJsonl=await file.text()}
async function submit(){formError.value='';try{if(!form.value.label.trim())throw new Error('请填写评测名称');validateDataset(form.value.inlineJsonl);saving.value=true;job.value=(await createEvaluation(form.value)).data;open.value=false;jobOpen.value=true;await load()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
function report(id:Id){void router.push({path:'/paismart/governance/evaluations/review',query:{evaluationId:String(id)}})}
function showJob(row:Evaluation){job.value={jobId:row.jobId!,state:row.jobState||row.state};jobOpen.value=true}
onMounted(async()=>{void load();try{spaces.value=(await listSpaces()).rows}catch(e){pageError.value=errorText(e)}})
</script>
